#[path="../../src/media.rs"]mod media;
#[path="../../src/analysis.rs"]mod analysis;
fn main(){let(tx,rx)=std::sync::mpsc::channel();let result=analysis::load(std::path::Path::new("media-analysis.exe"),std::path::Path::new("Clips/wave-lanes-fixture.mp4"),6.0,&tx).unwrap();assert_eq!(result.sources.len(),3);assert!(!result.frames.is_empty());for(i,p)in result.sources.iter().enumerate(){let n=p.len()/3;let avg:Vec<f32>=p.chunks(n).take(3).map(|c|c.iter().sum::<f32>()/c.len()as f32).collect();println!("source={i} thirds={avg:?}");assert!(avg[i]>0.05);for j in 0..3{if i!=j{assert!(avg[j]<0.02)}}}let early=rx.try_recv().unwrap().unwrap();assert_eq!(early.sources.len(),3);let cached=analysis::load(std::path::Path::new("media-analysis.exe"),std::path::Path::new("Clips/wave-lanes-fixture.mp4"),6.0,&tx).unwrap();assert_eq!(cached.sources,result.sources);println!("PASS separate source patterns, async update and cached source lanes");}
